+		// it as an unhandled rejection before the caller gets a chance to await it.
+		const promise = new Promise((resolve, reject) => {
+			queueItem.reject = reject;
+			enqueue(function_, resolve, arguments_, queueItem);
+		});
+		queueItem.promise = promise;
+
+		return promise;
+	};

